UPROPERTY(BlueprintReadOnly, Category = "Weapon Attribute Set", ReplicatedUsing= OnRep_WeaponResistance)
FGameplayAttributeData WeaponResistance;
ATTRIBUTE_ACCESSORS(UBaseCharAttributeSet, WeaponResistance)

FGameplayEffectSpecHandle SpecHandle = MakeOutgoingSpec(GE_WeaponClass, 1.f, Context);
SpecHandle.Data->SetSetByCallerMagnitude(FGameplayTag::RequestGameplayTag("Zerolock.DamageCalc.Weapon", false), DamageValue);
ApplyGameplayEffectSpecToTarget(*SpecHandle.Data.Get(), TargetASC);

FGameplayEventData WeaponHitEventData;
WeaponHitEventData.EventTag = FGameplayTag::RequestGameplayTag("Event.WeaponHit", false);
UAbilitySystemBlueprintLibrary::SendGameplayEventToActor(GetAvatarActor(), FGameplayTag::RequestGameplayTag("Event.WeaponHit", false), WeaponHitEventData);

MitigatedDamage = ((Damage + FlatWeapon) * (1 + WeaponDamage / 100)) * (1 - (WeaponResistance - WeaponResistanceReduction) / 100);

float HealAmount = MitigatedDamage * (WeaponLifeSteal / 100);
mySourceASC->ApplyHeal(mySourceASC, HealAmount);

OutExecutionOutput.AddOutputModifier(FGameplayModifierEvaluatedData(WeaponDamageStatics().DamageProperty, EGameplayModOp::Additive, MitigatedDamage));
